#!/usr/bin/env node
/*
 * Structural gate for the home desk and the styleguide ingredient ids.
 *
 * Reads the built dist/ (run `pnpm build` first) and checks the markup with
 * regexes only: the HTML is generated by Astro, so its shape is predictable.
 * Prints every failure and exits 1 if there is at least one.
 */

import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..');
const dist = resolve(root, 'dist');

const homeFile = resolve(dist, 'index.html');
const guideFile = resolve(dist, 'styleguide', 'index.html');
for (const file of [homeFile, guideFile]) {
  if (!existsSync(file)) {
    console.error(`${file} is missing. Run \`pnpm build\` first.`);
    process.exit(1);
  }
}

const read = (file) => readFileSync(file, 'utf8');
const readJson = (...parts) => JSON.parse(read(resolve(root, ...parts)));

const home = read(homeFile);
const guide = read(guideFile);
const icons = readJson('src', 'data', 'icons.json');
const styleguide = readJson('src', 'data', 'styleguide.es.json');

const failures = [];
const fail = (message) => failures.push(message);

/* attribute map of one tag: boolean attributes are `true` */
function attrs(tag) {
  const out = {};
  const body = tag.replace(/^<[\w-]+/, '').replace(/\/?>$/, '');
  for (const m of body.matchAll(/([\w:@.-]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g)) {
    out[m[1]] = m[2] ?? m[3] ?? m[4] ?? true;
  }
  return out;
}

const tags = (html, name) => [...html.matchAll(new RegExp(`<${name}\\b[^>]*>`, 'g'))].map((m) => m[0]);
const ids = new Set([...home.matchAll(/\sid="([^"]+)"/g)].map((m) => m[1]));

/* --- desk windows --- */

const deskMain = tags(home, 'main').find((tag) => 'data-desk' in attrs(tag));
if (!deskMain) fail('/: no <main data-desk>');

const windows = [];
for (const m of home.matchAll(/<section\b[^>]*>/g)) {
  const a = attrs(m[0]);
  if (!String(a.class ?? '').split(/\s+/).includes('window') || !a['data-app']) continue;
  const rest = home.slice(m.index + m[0].length);
  const bar = rest.match(/^\s*<header\b[^>]*class="[^"]*\bwindow__bar\b[^"]*"[^>]*>([\s\S]*?)<\/header>/);
  windows.push({ app: a['data-app'], id: a.id, labelledby: a['aria-labelledby'], bar: bar ? bar[1] : null });
}

if (windows.length === 0) fail('/: no desk windows (.window[data-app])');

for (const win of windows) {
  const who = `/ window "${win.app}"`;
  if (!win.id) fail(`${who}: no id`);
  if (win.id && win.id !== win.app) fail(`${who}: id "${win.id}" differs from data-app`);
  if (!win.labelledby) fail(`${who}: no aria-labelledby`);
  else if (!ids.has(win.labelledby)) fail(`${who}: aria-labelledby="${win.labelledby}" points at no id`);
  if (win.bar === null) {
    fail(`${who}: no .window__bar header right after the section`);
    continue;
  }

  const links = tags(win.bar, 'a').filter((tag) => 'data-nojs-close' in attrs(tag));
  if (links.length !== 1) fail(`${who}: ${links.length} no-JS close links, expected 1`);
  else if (!ids.has(String(attrs(links[0]).href ?? '').replace(/^#/, ''))) {
    fail(`${who}: no-JS close link href "${attrs(links[0]).href}" resolves to no id`);
  }

  const buttons = tags(win.bar, 'button').map(attrs);
  for (const action of ['min', 'max', 'close']) {
    const found = buttons.filter((b) => b['data-win'] === action);
    if (found.length !== 1) fail(`${who}: ${found.length} [data-win="${action}"] buttons, expected 1`);
    else if (!('hidden' in found[0])) fail(`${who}: [data-win="${action}"] is not hidden`);
  }
}

/* --- icons --- */

const cells = Object.keys(icons).length;
const iconTags = tags(home, 'a').filter((tag) => 'data-desk-icon' in attrs(tag));
if (iconTags.length === 0) fail('/: no [data-desk-icon] links');

for (const tag of iconTags) {
  const a = attrs(tag);
  const key = a['data-desk-icon'];
  const who = `/ icon "${key}"`;
  const href = String(a.href ?? '');

  if (href.startsWith('#')) {
    if (!windows.some((win) => win.id === href.slice(1))) fail(`${who}: href "${href}" matches no .window[data-app]`);
  } else if (href.startsWith('/')) {
    const path = resolve(dist, href.slice(1));
    if (!existsSync(path) && !existsSync(resolve(path, 'index.html'))) fail(`${who}: href "${href}" is not a built page`);
  } else {
    fail(`${who}: href "${href}" is neither #window nor a site path`);
  }

  if (!(key in icons)) {
    fail(`${who}: key is not in src/data/icons.json`);
    continue;
  }
  const i = String(a.style ?? '').match(/--i:\s*(\d+)/);
  if (!i) fail(`${who}: no --i in its style`);
  else if (Number(i[1]) >= cells) fail(`${who}: --i:${i[1]} is outside the ${cells}-cell atlas`);
  else if (Number(i[1]) !== icons[key].i) fail(`${who}: --i:${i[1]} but icons.json says ${icons[key].i}`);
}

/* the 16 px title-bar icons index the same atlas */
for (const m of home.matchAll(/<span\b[^>]*window__icon--atlas[^>]*>/g)) {
  const i = String(attrs(m[0]).style ?? '').match(/--i:\s*(\d+)/);
  if (!i || Number(i[1]) >= cells) fail(`/: a title-bar atlas icon has --i out of range (${i ? i[1] : 'missing'})`);
}

/* --- headings --- */

const h1 = (home.match(/<h1\b/g) ?? []).length;
if (h1 !== 1) fail(`/: ${h1} <h1> elements, expected exactly 1`);

/* --- inline styles carry no colour (colours come from tokens) --- */

const NAMED = 'black|white|red|green|blue|yellow|orange|purple|pink|gray|grey|silver|navy|teal|aqua|lime|maroon|olive|fuchsia|cyan|magenta|brown|gold';
const COLOUR = new RegExp(
  `#[0-9a-f]{3,8}\\b|\\b(?:rgba?|hsla?|hwb|lab|lch|oklab|oklch|color|color-mix)\\(|\\b(?:${NAMED})\\b`,
  'i',
);
for (const m of home.matchAll(/\sstyle="([^"]*)"/g)) {
  /* var(--token) is the allowed way to reach a colour */
  const value = m[1].replace(/var\([^)]*\)/g, '');
  if (COLOUR.test(value)) fail(`/: inline style carries a colour value: style="${m[1]}"`);
}

/* --- styleguide ingredient ids --- */

const wanted = [...(styleguide.items ?? []), ...(styleguide.themes?.items ?? [])].map((item) => item.id);
const rendered = new Set([...guide.matchAll(/\sid="(ing-[^"]+)"/g)].map((m) => m[1]));
for (const id of wanted) {
  if (!rendered.has(`ing-${id}`)) fail(`/styleguide/: ingredient "${id}" does not render id="ing-${id}"`);
}

/* --- report --- */

if (failures.length) {
  console.error(`check:desk · ${failures.length} failure${failures.length === 1 ? '' : 's'}`);
  for (const message of failures) console.error(`  ✗ ${message}`);
  process.exit(1);
}

console.log(
  `check:desk · ok · ${windows.length} windows, ${iconTags.length} icons, ${wanted.length} styleguide ingredients`,
);
